begin
 perform controlled_count_entry_v1.shared_product_resource_origin_catalog_required();
 if not exists(select 1 from pg_catalog.pg_locks l where l.locktype='advisory'
 and l.pid=pg_catalog.pg_backend_pid()and l.database=(select oid from pg_catalog.pg_database where datname=pg_catalog.current_database())
 and l.classid=90271040::oid and l.objid=0::oid and l.objsubid=2
 and l.mode='ShareLock'and l.granted)then
  raise exception 'count_frontier_invalid'using errcode='P0001',detail='',hint='';end if;
 for r in select p.*,c.oid as relation_oid,c.relkind,c.relispartition
 from controlled_count_entry_v1.shared_product_relation_plan_values()p
 left join pg_catalog.pg_namespace n on n.nspname=p.schema_name
 left join pg_catalog.pg_class c on c.relnamespace=n.oid and c.relname=p.relation_name loop
  seen:=seen+1;
  if r.relation_oid is null or r.relkind<>'r'or r.relispartition
  or not exists(select 1 from pg_catalog.pg_locks l where l.locktype='relation'
   and l.pid=pg_catalog.pg_backend_pid()and l.database=(select oid from pg_catalog.pg_database where datname=pg_catalog.current_database())
   and l.relation=r.relation_oid and l.mode=r.held_mode and l.granted)then
   raise exception 'count_frontier_invalid'using errcode='P0001',detail='',hint='';end if;
 end loop;
 if seen<>121 then raise exception 'count_frontier_invalid'using errcode='P0001',detail='',hint='';end if;
end

