controlled_count_v1.readcore_saved_snaps.new_expression:
 -- Validate the complete header/value shape here. The immediately following
 -- saved_boundary_manifest validates the SAME immutable PB before return.
 declare p_document jsonb:=r->'document';key_value text;participants jsonb;a jsonb;b jsonb;policy_doc jsonb;
begin
 if p_document is null or octet_length(p_document::text)>16777216
 or controlled_count_v1.count_wire_keys(p_document,array['schema_version','domain','id','count_id','product_id','site_id','captured_at','policy','participants','physical_boundary','physical_boundary_hash','unit_manifest','container_manifest','location_ids','record_hash'])is not true
 or p_document->'schema_version'is distinct from '1'::jsonb or(p_document->'schema_version')::text is distinct from '1'
 or p_document->'domain'is distinct from '"lrv-controlled-count-snapshot-v1"'::jsonb then
  raise exception 'count_value_invalid'using errcode='P0001',detail='',hint='';end if;
 foreach key_value in array array['id','count_id','product_id','site_id']loop
  if controlled_count_v1.count_wire_uuid(p_document->key_value)is not true then raise exception 'count_value_invalid'using errcode='P0001',detail='',hint='';end if;
 end loop;
 if controlled_count_v1.count_wire_time(p_document->'captured_at')is not true then raise exception 'count_value_invalid'using errcode='P0001',detail='',hint='';end if;
 perform controlled_count_v1.saved_require_hash(p_document->'record_hash');perform controlled_count_v1.saved_require_hash(p_document->'physical_boundary_hash');
 if p_document->>'record_hash'is distinct from controlled_count_v1.document_hash(p_document)
 or p_document->>'physical_boundary_hash'is distinct from controlled_count_v1.saved_boundary_hash(p_document->'physical_boundary')then
  raise exception 'count_source_invalid'using errcode='P0001',detail='',hint='';end if;

 perform controlled_count_v1.observation_manifest_values(jsonb_build_object('units',p_document->'unit_manifest','containers',p_document->'container_manifest'));
 perform controlled_count_v1.saved_uuid_array_values(p_document->'location_ids',4096);
 policy_doc:=controlled_count_v1.policy_values(p_document->'policy');participants:=p_document->'participants';
 if controlled_count_v1.count_wire_keys(participants,array['actor_a','actor_b'])is not true then raise exception 'count_value_invalid'using errcode='P0001',detail='',hint='';end if;
 a:=controlled_count_v1.actor_values(participants->'actor_a');b:=participants->'actor_b';
 if controlled_count_v1.count_wire_keys(b,array['id','name','live_roles','policy_id','policy_hash'])is not true
 or controlled_count_v1.count_wire_uuid(b->'id')is not true or controlled_count_v1.count_wire_uuid(b->'policy_id')is not true then
  raise exception 'count_value_invalid'using errcode='P0001',detail='',hint='';end if;
 perform public.controlled_stock_text(b->'name',200,false);perform controlled_count_v1.role_set_values(b->'live_roles',true);perform controlled_count_v1.saved_require_hash(b->'policy_hash');
 if a->'id'=b->'id'or a#>'{current_authorization,capability}'is distinct from '"observe"'::jsonb
 or policy_doc->'product_id'is distinct from p_document->'product_id'or policy_doc->'site_id'is distinct from p_document->'site_id'
 or a#>'{current_authorization,product_id}'is distinct from p_document->'product_id'or a#>'{current_authorization,site_id}'is distinct from p_document->'site_id'
 or a#>'{current_authorization,policy_id}'is distinct from policy_doc->'policy_id'or a#>'{current_authorization,policy_hash}'is distinct from policy_doc->'record_hash'
 or b->'policy_id'is distinct from policy_doc->'policy_id'or b->'policy_hash'is distinct from policy_doc->'record_hash'
 or controlled_count_v1.policy_capability_values(policy_doc,a#>'{current_authorization,live_roles}','observe')is not true
 or controlled_count_v1.policy_capability_values(policy_doc,b->'live_roles','observe')is not true
 or(policy_doc->>'recorded_at')::timestamptz>(p_document->>'captured_at')::timestamptz then
  raise exception 'count_source_invalid'using errcode='P0001',detail='',hint='';end if;
 d:=p_document;
end;

